const ok = r => r && r.statusCode >= 200 && r.statusCode < 300;
const bodyOf = r => (r && r.body && typeof r.body === 'object' ? r.body : {});
const errText = r => { r = r || {}; const b = r.body; const e = (b && typeof b === 'object' ? (b.detail ?? b.message) : b) ?? r.error?.message ?? r.error; return e == null || e === '' ? 'no answer' : String(typeof e === 'object' ? JSON.stringify(e) : e).slice(0, 300); };

const r = $input.first().json;
if (!$env.FLOW_URL) return [{ json: { go: false, notify: false, text: '*Email flows*: FLOW_URL is not set. Nothing to do.' } }];
if (!ok(r)) return [{ json: { go: false, notify: true, text: `*Email flows*: flow-runner (86) did not answer (${r.statusCode || 'no response'}: ${errText(r)}).` } }];
return [{ json: { go: true } }];

const ok = r => r && r.statusCode >= 200 && r.statusCode < 300;
const bodyOf = r => (r && r.body && typeof r.body === 'object' ? r.body : {});
const errText = r => { r = r || {}; const b = r.body; const e = (b && typeof b === 'object' ? (b.detail ?? b.message) : b) ?? r.error?.message ?? r.error; return e == null || e === '' ? 'no answer' : String(typeof e === 'object' ? JSON.stringify(e) : e).slice(0, 300); };

const s = $('Sync reviews').first().json, t = $('Tick').first().json;
const sb = bodyOf(s), tb = bodyOf(t);
const lines = [], problems = [];
const list = a => (Array.isArray(a) ? a : []);
if (!ok(s)) problems.push(`review sync failed (${s.statusCode || 'no response'}: ${errText(s)})`);
else {
  if (list(sb.created).length) lines.push(`*Email flow waiting for approval*: ${list(sb.created).map(c => c.version).join(', ')} (the whole sequence is one item in the calendar).`);
  if (list(sb.approved).length) lines.push(`*Email flow approved*: ${list(sb.approved).join(', ')}. It runs for contacts who enter from now on.`);
  if (list(sb.rejected).length) lines.push(`*Email flow rejected*: ${list(sb.rejected).join(', ')}. The approved version, if any, keeps running.`);
  if (list(sb.waiting_for_approver_key).length) problems.push(`approved in review but n8n has no APPROVER_KEY: ${list(sb.waiting_for_approver_key).join(', ')}`);
  problems.push(...list(sb.problems));
}
if (!ok(t)) problems.push(`tick failed (${t.statusCode || 'no response'}: ${errText(t)})`);
else {
  const by = Object.entries(tb.by_flow || {}).map(([f, n]) => `${f} ${n}`).join(', ');
  if (tb.sent > 0) lines.push(tb.dry_run
    ? `*Email flows (dry run)*: ${tb.sent} email${tb.sent === 1 ? '' : 's'} written to the outbox, nothing delivered (${by}).`
    : `*Email flows*: ${tb.sent} email${tb.sent === 1 ? '' : 's'} sent (${by}).`);
  if (tb.failed > 0) problems.push(`${tb.failed} send${tb.failed === 1 ? '' : 's'} failed (GET /outbox?status=failed)`);
  for (const n of list(tb.notices)) lines.push(`*Email flows*: ${n}`);
}
if (problems.length) lines.push(`*Email flow problems*: ${problems.slice(0, 5).join('; ')}`);
return [{ json: { notify: lines.length > 0, text: lines.join('\n'), waits: list(sb.created).length > 0,
  sent: ok(t) ? tb.sent || 0 : 0, problems: problems.length } }];

function notifyRequest(text, env, waits) {
  const fmt = String(env.NOTIFY_FORMAT || 'generic').trim().toLowerCase();
  const telegram = fmt === 'telegram';
  if (telegram ? !(env.TELEGRAM_BOT_TOKEN && env.TELEGRAM_CHAT_ID) : !env.NOTIFY_WEBHOOK_URL) return null;
  const plain = String(text ?? '');
  const form = `${String(env.N8N_PUBLIC_URL || 'http://localhost:5678/').trim().replace(/\/?$/, '/')}form/mkt-content-approval`;
  const link = waits && !plain.includes(form) ? form : null;   // already in the text: once is enough
  // Cut the text (never the link) to the longest prefix whose rendered message fits:
  // escaping can make the rendered text several times longer, so search for it.
  const fit = (render, max) => {
    if (render(plain).length <= max) return render(plain);
    let lo = 0, hi = plain.length;
    while (lo < hi) {
      const mid = Math.ceil((lo + hi) / 2);
      if (render(plain.slice(0, mid).trimEnd() + '…').length <= max) lo = mid; else hi = mid - 1;
    }
    return render(plain.slice(0, lo).trimEnd() + '…');
  };
  const mdLink = /\[([^\]\n]+)\]\((https?:\/\/[^\s)"<>]+)\)/g;
  const oneStar = /(^|[^*\w])\*(?![\s*])([^*\n]*?[^\s*])\*(?![*\w])/g;   // Slack-style *bold*
  const heading = /^#{1,6}[ \t]+(.+)$/gm;
  if (telegram) {
    const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const render = t => esc(t)
      .replace(mdLink, '<a href="$2">$1</a>')
      .replace(/\*\*([^*\n]+)\*\*/g, '<b>$1</b>').replace(oneStar, '$1<b>$2</b>').replace(heading, '<b>$1</b>')
      + (link ? `\n\n<a href="${esc(link)}">Open the approval form</a>` : '');
    const api = String(env.TELEGRAM_API_URL || 'https://api.telegram.org').trim().replace(/\/+$/, '');
    return { format: 'telegram', url: `${api}/bot<TELEGRAM_BOT_TOKEN>/sendMessage`, body: {
      chat_id: String(env.TELEGRAM_CHAT_ID).trim(), text: fit(render, 4096), parse_mode: 'HTML',
      disable_web_page_preview: true } };
  }
  const url = '<NOTIFY_WEBHOOK_URL>';
  if (fmt === 'slack') {
    const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const render = t => esc(t)
      .replace(mdLink, '<$2|$1>').replace(/\*\*([^*\n]+)\*\*/g, '*$1*').replace(heading, '*$1*')
      + (link ? `\n\n<${link}|Open the approval form>` : '');
    return { format: 'slack', url, body: { text: fit(render, 40000) } };
  }
  if (fmt === 'discord') {
    // <url> stops link previews; Discord bold is **x**; nothing in the text can ping anyone.
    const render = t => t.replace(oneStar, '$1**$2**').replace(/(^|\s)(https?:\/\/[^\s<>]+)/g, '$1<$2>')
      + (link ? `\n\nApproval form: <${link}>` : '');
    return { format: 'discord', url, body: { content: fit(render, 2000), allowed_mentions: { parse: [] } } };
  }
  const t = link ? `${plain.trimEnd()}\n\nApproval form: ${link}` : plain;
  return { format: 'generic', url, body: { text: t, content: t } };   // the payload before NOTIFY_FORMAT
}

return $input.all().flatMap(item => {
  const req = notifyRequest(item.json.text, $env, item.json.waits);
  return req ? [{ json: req }] : [];
});
